<script>
  import { computeComplexSpectral, computeCachedLineSearch } from '@/lib/formula-lessons/part4-models.mjs';
  export let lesson; export let spec; let N=spec.N??9,alpha=spec.alpha??.4;
  $: spectral=spec.scene==='complex-spectral'?computeComplexSpectral({N:Number(N),Lpsi:spec.Lpsi,pNorm:spec.pNorm,z:spec.z}):null; $: cached=spec.scene==='cached-line-search'?computeCachedLineSearch({x:spec.x,d:spec.d,alpha:Number(alpha)}):null; const f=(v,d=5)=>Number(v).toFixed(d);
</script>
<div class="lesson-grid" data-part4-spectral-line-search data-focus={lesson.focus} data-scene={spec.scene}>{#if spectral}<section class="panel"><p class="eyebrow">periodic first-difference spectrum</p><div class="metrics"><div><span>N</span><strong>{spectral.N}</strong></div><div><span>ρ(C) direct</span><strong>{f(spectral.rho)}</strong></div><div><span>corrected formula</span><strong>{f(spectral.correctedOdd)}</strong></div><div><span>residual</span><strong>{f(spectral.spectralResidual,8)}</strong></div></div><label>N <output>{N}</output><input bind:value={N} type="range" min="3" max="15" step="2"/></label><div class="freq">{#each Array.from({length:Number(N)},(_,k)=>2*Math.abs(Math.sin(Math.PI*k/Number(N)))) as value,k (k)}<div title={`k=${k}, |λ|=${f(value,3)}`} style={`height:${8+60*value/2}px`}></div>{/each}</div></section><section class="panel"><p class="eyebrow">transformed smoothness → safe step</p><div class="metrics"><div><span>||P||₂ Lψ upper</span><strong>{f(spectral.transformedLipschitzUpper,3)}</strong></div><div><span>α upper</span><strong>{f(spectral.safeStepUpper,4)}</strong></div><div><span>Re〈g,d〉</span><strong>{f(spectral.complexDescentInnerReal,3)}</strong></div><div><span>descent?</span><strong>{spectral.descent?'PASS':'FAIL'}</strong></div></div><p class="note">103/109/111 remain source-suspect; 213/219/220 carry the corrected spectrum, upper-bound semantics, and safe step.</p></section>{:else if cached}<section class="panel"><p class="eyebrow">cached trial products</p><label>α <output>{f(alpha,2)}</output><input bind:value={alpha} type="range" min="-.5" max="1.2" step=".05"/></label><div class="table-wrap"><table><thead><tr><th>i</th><th>direct</th><th>cached</th><th>residual</th></tr></thead><tbody>{#each cached.rows as row,i (i)}<tr><td>{i+1}</td><td>[{row.direct.map(v=>f(v,3)).join(', ')}]</td><td>[{row.cached.map(v=>f(v,3)).join(', ')}]</td><td>{f(row.residual,8)}</td></tr>{/each}</tbody></table></div></section><section class="panel"><p class="eyebrow">accepted-step cache update</p><p class="vector">x⁺=[{cached.trialX.map(v=>f(v,3)).join(', ')}]</p>{#each cached.nextCaches as row,i (i)}<p class="vector">z{i+1}⁺=[{row.map(v=>f(v,3)).join(', ')}]</p>{/each}<div class="metrics"><div><span>max residual</span><strong>{f(cached.maxResidual,10)}</strong></div><div><span>identity</span><strong>{cached.maxResidual<1e-10?'PASS':'FAIL'}</strong></div></div><p class="note">§4.5의 핵심은 trial마다 Bᵢ product를 다시 계산하지 않는 것이다.</p></section>{/if}</div>
<style>.lesson-grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0 0 .5rem;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.metrics div{display:grid;background:var(--color-muted);border-radius:.65rem;padding:.55rem;font-size:.72rem}.metrics span{color:var(--color-muted-foreground)}label{display:grid;grid-template-columns:1fr auto;margin-top:.6rem;font-size:.72rem;font-weight:800}input{grid-column:1/-1;min-height:30px}.freq{height:90px;display:flex;align-items:flex-end;gap:.25rem;margin-top:.7rem}.freq div{flex:1;min-width:4px;border-radius:.2rem .2rem 0 0;background:var(--color-primary)}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.68rem}th,td{padding:.4rem;border-bottom:1px solid var(--color-border);text-align:right;white-space:nowrap}.vector{font-family:ui-monospace,monospace;font-size:.74rem}.note{font-size:.73rem;line-height:1.65;color:var(--color-muted-foreground)}@media(max-width:760px){.lesson-grid{grid-template-columns:1fr}}</style>
